import uuid
from datetime import datetime

from sqlalchemy import DateTime, String, Text, Uuid, func
from sqlalchemy.orm import Mapped, mapped_column

from app.database import Base, utc_now
from app.rules import MAX_TITLE_LENGTH


class ThemeHint(Base):
    """An idea shown while writing a challenger title on a day of the theme,
    e.g. "a challenger who burns dinner every night" for the volcano.

    Add rows any time; a hint is used from the day after it was created on,
    so a day's picks never change.
    """

    __tablename__ = "theme_hint"

    # Generated by the database too, for rows added by hand.
    id: Mapped[uuid.UUID] = mapped_column(
        Uuid,
        primary_key=True,
        default=uuid.uuid4,
        server_default=func.gen_random_uuid(),
    )
    # An `app.rules.Theme`.
    theme: Mapped[str] = mapped_column(String(20), nullable=False, index=True)
    text: Mapped[str] = mapped_column(Text, nullable=False)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        default=utc_now,
        server_default=func.now(),
    )


class PremadeTitle(Base):
    """A challenger title that stands in when nobody wrote one on a day of
    the theme. Like hints, used from the day after it was created on."""

    __tablename__ = "premade_title"

    # Generated by the database too, for rows added by hand.
    id: Mapped[uuid.UUID] = mapped_column(
        Uuid,
        primary_key=True,
        default=uuid.uuid4,
        server_default=func.gen_random_uuid(),
    )
    # An `app.rules.Theme`.
    theme: Mapped[str] = mapped_column(String(20), nullable=False, index=True)
    title: Mapped[str] = mapped_column(String(MAX_TITLE_LENGTH), nullable=False)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        default=utc_now,
        server_default=func.now(),
    )
